fn main() {
    let nama = "Budi";        // variabel immutable
    let mut umur = 25;        // variabel mutable
    umur = umur + 1;          // nilai boleh diubah
    const PI: f64 = 3.14159;  // konstanta (selalu tetap)

    println!("Nama: {}", nama);
    println!("Umur: {}", umur);
    println!("Nilai PI: {}", PI);
}

fn main() {
    let bilangan_bulat: i32 = -42;     // bilangan bulat
    let bilangan_desimal: f64 = 3.14;  // bilangan pecahan
    let benar: bool = true;            // boolean
    let huruf: char = 'R';             // satu karakter
    let teks: &str = "Halo, Rust!";    // teks (string slice)

    println!("{}", bilangan_bulat);
    println!("{}", bilangan_desimal);
    println!("{} {} {}", benar, huruf, teks);
}

fn main() {
    let a = 10;
    let b = 3;

    // Operator aritmetika
    println!("Penjumlahan : {}", a + b);  // 13
    println!("Pengurangan : {}", a - b);  // 7
    println!("Perkalian   : {}", a * b);  // 30
    println!("Pembagian   : {}", a / b);  // 3
    println!("Sisa bagi   : {}", a % b);  // 1

    // Operator perbandingan dan logika
    let hasil = (a > b) && (b > 0);
    println!("a lebih besar dari b: {}", hasil);  // true
}

fn main() {
    let nilai = 75;

    if nilai >= 90 {
        println!("Grade: A");
    } else if nilai >= 75 {
        println!("Grade: B");
    } else {
        println!("Grade: C");
    }
}

fn main() {
    let nilai = 75;
    let status = if nilai >= 60 { "Lulus" } else { "Gagal" };
    println!("Status: {}", status);
}

fn main() {
    // Iterasi rentang 1 sampai 5
    for i in 1..=5 {
        println!("Iterasi ke-{}", i);
    }

    // Iterasi elemen array
    let angka = [10, 20, 30];
    for nilai in angka {
        println!("Nilai: {}", nilai);
    }
}

fn main() {
    let mut hitung = 3;

    while hitung > 0 {
        println!("Hitung mundur: {}", hitung);
        hitung -= 1;
    }
    println!("Selesai!");
}

fn main() {
    let mut counter = 0;

    let hasil = loop {
        counter += 1;
        if counter == 5 {
            break counter * 2;  // keluar sambil mengembalikan nilai
        }
    };
    println!("Hasil: {}", hasil);  // 10
}

fn main() {
    sapa();  // memanggil fungsi sapa
    sapa();  // dapat dipanggil berkali-kali
}

// Definisi fungsi tanpa parameter
fn sapa() {
    println!("Selamat datang di Rust!");
}

fn main() {
    tampilkan_jumlah(5, 7);
    tampilkan_jumlah(100, 250);
}

fn tampilkan_jumlah(a: i32, b: i32) {
    println!("{} + {} = {}", a, b, a + b);
}

fn main() {
    let hasil = tambah(8, 4);
    println!("Hasil penjumlahan: {}", hasil);  // 12

    println!("5 kuadrat = {}", kuadrat(5));    // 25
}

// Nilai dikembalikan lewat ekspresi terakhir
fn tambah(a: i32, b: i32) -> i32 {
    a + b
}

// Nilai dikembalikan secara eksplisit dengan return
fn kuadrat(x: i32) -> i32 {
    return x * x;
}
